// USDA SR Legacy foods that Indian users eat, with Indian-friendly names and
// search aliases (Hindi, Hinglish and regional names in Latin script, plus
// English variants). Values come from data/usda/sr_legacy_macros.csv by fdcId
// (USDA FoodData Central, public domain). Names and aliases are ours.
//
// Where USDA has no exact Indian match, the closest USDA food is named so the
// difference is visible, e.g. "Carp (rohu/katla type)", "Shad (hilsa family)",
// "Millet (proso/bajra type)".

export interface RawFood {
  /** USDA FoodData Central id (SR Legacy). */
  fdcId: number
  name: string
  /** What people type when searching: Hinglish, regional and English names. */
  aliases: string[]
}

